import queue
import threading
import time


class BoundedBuffer:
    def __init__(self, capacity):
        self.buffer = queue.Queue(maxsize=capacity)

    def put(self, item):
        if self.buffer.full():
            print(f"Buffer full, producer blocked (backpressure) at item {item}")
        self.buffer.put(item)  # blocks here until the consumer drains a slot
        print(f"Produced {item}, buffer size={self.buffer.qsize()}")

    def take(self):
        item = self.buffer.get()
        print(f"Consumed {item}, buffer size={self.buffer.qsize()}")
        return item


def produce(buffer, count):
    for i in range(1, count + 1):
        buffer.put(i)


def consume(buffer, count):
    for _ in range(count):
        time.sleep(0.05)
        buffer.take()


if __name__ == "__main__":
    bounded_buffer = BoundedBuffer(3)
    count = 6

    producer_thread = threading.Thread(target=produce, args=(bounded_buffer, count))
    consumer_thread = threading.Thread(target=consume, args=(bounded_buffer, count))

    producer_thread.start()
    consumer_thread.start()
    producer_thread.join()
    consumer_thread.join()

