#include <iostream>
#include <queue>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>

class BoundedBuffer {
public:
    explicit BoundedBuffer(std::size_t capacity) : capacity_(capacity) {}

    void put(int item) {
        std::unique_lock<std::mutex> lock(mutex_);
        if (buffer_.size() == capacity_) {
            std::cout << "Buffer full, producer blocked (backpressure) at item " << item << std::endl;
        }
        notFull_.wait(lock, [this] { return buffer_.size() < capacity_; });
        buffer_.push(item);
        std::cout << "Produced " << item << ", buffer size=" << buffer_.size() << std::endl;
        notEmpty_.notify_all();
    }

    int take() {
        std::unique_lock<std::mutex> lock(mutex_);
        notEmpty_.wait(lock, [this] { return !buffer_.empty(); });
        int item = buffer_.front();
        buffer_.pop();
        std::cout << "Consumed " << item << ", buffer size=" << buffer_.size() << std::endl;
        notFull_.notify_all();
        return item;
    }

private:
    std::queue<int> buffer_;
    std::size_t capacity_;
    std::mutex mutex_;
    std::condition_variable notFull_;
    std::condition_variable notEmpty_;
};

int main() {
    BoundedBuffer boundedBuffer(3);
    const int count = 6;

    std::thread producer([&boundedBuffer, count] {
        for (int i = 1; i <= count; ++i) {
            boundedBuffer.put(i);
        }
    });

    std::thread consumer([&boundedBuffer, count] {
        for (int i = 0; i < count; ++i) {
            std::this_thread::sleep_for(std::chrono::milliseconds(50));
            boundedBuffer.take();
        }
    });

    producer.join();
    consumer.join();
    return 0;
}
